INSERT INTO scale_configs (scale_config_id, scale_code, name, version, category, source_document, instructions, items, scoring, stimulus_assets, status) VALUES ('scd_q9-1.0', 'SCD_Q9', '主观认知下降自测表', '1.0', 'screening', '1_AD临床前期SCD筛查量表-基线期-加上情景选择题.pdf', '["请根据自身实际情况作答。评分标准：是=1分、否=0分；经常=1分、偶尔=0.5分、从未=0分。最后得分=各题得分之和（0~9分）。"]'::jsonb, '[{"code":"SCD_Q9_01","no":1,"text":"你认为自己有记忆问题吗？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]},{"code":"SCD_Q9_02","no":2,"text":"你回忆 3-5 天前的对话有困难吗？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]},{"code":"SCD_Q9_03","no":3,"text":"你觉得自己近两年有记忆问题吗？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]},{"code":"SCD_Q9_04","no":4,"text":"下列问题经常发生吗：忘记对个人来说重要的日期（如生日等）","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"经常","text":"经常","score":1.0,"is_na":false},{"code":"偶尔","text":"偶尔","score":0.5,"is_na":false},{"code":"从未","text":"从未","score":0.0,"is_na":false}]},{"code":"SCD_Q9_05","no":5,"text":"下列问题经常发生吗：忘记常用号码","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"经常","text":"经常","score":1.0,"is_na":false},{"code":"偶尔","text":"偶尔","score":0.5,"is_na":false},{"code":"从未","text":"从未","score":0.0,"is_na":false}]},{"code":"SCD_Q9_06","no":6,"text":"总的来说，你是否认为自己对要做的事或要说的话容易忘记？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]},{"code":"SCD_Q9_07","no":7,"text":"下列问题经常发生吗：到了商店忘记要买什么","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"经常","text":"经常","score":1.0,"is_na":false},{"code":"偶尔","text":"偶尔","score":0.5,"is_na":false},{"code":"从未","text":"从未","score":0.0,"is_na":false}]},{"code":"SCD_Q9_08","no":8,"text":"你认为自己的记忆力比 5 年前要差吗？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]},{"code":"SCD_Q9_09","no":9,"text":"你认为自己越来越记不住东西放哪儿了吗？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]}]'::jsonb, '{"scoringType":"SUM","scoreMin":0.0,"scoreMax":9.0,"cutoffs":[],"remark":"参考评分标准见量表原版；本量表总分越高提示主观记忆下降越明显。","algorithmSource":"scoring/scales/scd_q9.py"}'::jsonb, '[]'::jsonb, 'draft');
INSERT INTO scale_configs (scale_config_id, scale_code, name, version, category, source_document, instructions, items, scoring, stimulus_assets, status) VALUES ('gds-1.0', 'GDS', '老年抑郁量表', '1.0', 'screening', '1_AD临床前期SCD筛查量表-基线期-加上情景选择题.pdf', '["选择最切合你最近一周感受的答案。15 个条目中有 5 条反序计分（回答「否」表示抑郁存在），10 条正序计分（回答「是」表示抑郁存在）。"]'::jsonb, '[{"code":"GDS_01","no":1,"text":"你对你的生活基本满意吗？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":0.0,"is_na":false},{"code":"否","text":"否","score":1.0,"is_na":false}]},{"code":"GDS_02","no":2,"text":"你是否已经放弃了许多爱好与兴趣？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]},{"code":"GDS_03","no":3,"text":"你是否觉得生活空虚？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]},{"code":"GDS_04","no":4,"text":"你是否感到厌倦？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]},{"code":"GDS_05","no":5,"text":"你是否大部分时间精力充沛？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":0.0,"is_na":false},{"code":"否","text":"否","score":1.0,"is_na":false}]},{"code":"GDS_06","no":6,"text":"你是否害怕会有不幸的事落到你头上？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]},{"code":"GDS_07","no":7,"text":"你是否大部分时间感到幸福？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":0.0,"is_na":false},{"code":"否","text":"否","score":1.0,"is_na":false}]},{"code":"GDS_08","no":8,"text":"你是否经常感到孤立无援？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]},{"code":"GDS_09","no":9,"text":"你是否愿意呆在家里而不愿去室外做些新鲜事？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]},{"code":"GDS_10","no":10,"text":"你是否觉得记忆力比以前差？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]},{"code":"GDS_11","no":11,"text":"你觉得现在活着很开心吗？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":0.0,"is_na":false},{"code":"否","text":"否","score":1.0,"is_na":false}]},{"code":"GDS_12","no":12,"text":"你是否觉得像现在这样活着毫无意义？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]},{"code":"GDS_13","no":13,"text":"你觉得生活充满活力吗？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":0.0,"is_na":false},{"code":"否","text":"否","score":1.0,"is_na":false}]},{"code":"GDS_14","no":14,"text":"你是否觉得你的处境已毫无希望？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]},{"code":"GDS_15","no":15,"text":"你是否觉得大多数人比你强得多？","domain":null,"max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"是","text":"是","score":1.0,"is_na":false},{"code":"否","text":"否","score":0.0,"is_na":false}]}]'::jsonb, '{"scoringType":"SUM","scoreMin":0.0,"scoreMax":15.0,"cutoffs":[{"cutoff_type":"LEVEL","group_key":"0-4","result_label":"正常","is_abnormal":false,"edu_years_min":null,"edu_years_max":null,"min_score":0.0,"max_score":4.0,"threshold":null},{"cutoff_type":"LEVEL","group_key":"5-8","result_label":"轻度抑郁","is_abnormal":false,"edu_years_min":null,"edu_years_max":null,"min_score":5.0,"max_score":8.0,"threshold":null},{"cutoff_type":"LEVEL","group_key":"9-11","result_label":"中度抑郁","is_abnormal":false,"edu_years_min":null,"edu_years_max":null,"min_score":9.0,"max_score":11.0,"threshold":null},{"cutoff_type":"LEVEL","group_key":"12-15","result_label":"重度抑郁","is_abnormal":true,"edu_years_min":null,"edu_years_max":null,"min_score":12.0,"max_score":15.0,"threshold":null}],"remark":"反序计分题：第 1、5、7、11、13 题。","algorithmSource":"scoring/scales/gds.py"}'::jsonb, '[]'::jsonb, 'draft');
INSERT INTO scale_configs (scale_config_id, scale_code, name, version, category, source_document, instructions, items, scoring, stimulus_assets, status) VALUES ('faq-1.0', 'FAQ', '功能活动问卷', '1.0', 'screening', '1_AD临床前期SCD筛查量表-基线期-加上情景选择题.pdf', '["由知情者完成，评价指标为项目总分。评分 0~3 四级：0=无困难；1=有些困难需指导或监督；2=部分依赖；3=无法完成或完全依赖；NA=该项目不适合或老人从来不做（不计入总分）。"]'::jsonb, '[{"code":"FAQ_01","no":1,"text":"使用电话或手机","domain":null,"max_score":3.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"0","text":"没有任何困难，能独立完成，不需他人帮助","score":0.0,"is_na":false},{"code":"1","text":"有些困难，需要他人指导或监督","score":1.0,"is_na":false},{"code":"2","text":"需要帮助才能完成，部分依赖","score":2.0,"is_na":false},{"code":"3","text":"本人无法完成，或完全由他人代替完成","score":3.0,"is_na":false},{"code":"NA","text":"该项目不适合，或老人从来不做","score":0.0,"is_na":true}]},{"code":"FAQ_02","no":2,"text":"整理家庭物品井井有条、不凌乱","domain":null,"max_score":3.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"0","text":"没有任何困难，能独立完成，不需他人帮助","score":0.0,"is_na":false},{"code":"1","text":"有些困难，需要他人指导或监督","score":1.0,"is_na":false},{"code":"2","text":"需要帮助才能完成，部分依赖","score":2.0,"is_na":false},{"code":"3","text":"本人无法完成，或完全由他人代替完成","score":3.0,"is_na":false},{"code":"NA","text":"该项目不适合，或老人从来不做","score":0.0,"is_na":true}]},{"code":"FAQ_03","no":3,"text":"自行购物（如购买衣服、食品及家庭用品）","domain":null,"max_score":3.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"0","text":"没有任何困难，能独立完成，不需他人帮助","score":0.0,"is_na":false},{"code":"1","text":"有些困难，需要他人指导或监督","score":1.0,"is_na":false},{"code":"2","text":"需要帮助才能完成，部分依赖","score":2.0,"is_na":false},{"code":"3","text":"本人无法完成，或完全由他人代替完成","score":3.0,"is_na":false},{"code":"NA","text":"该项目不适合，或老人从来不做","score":0.0,"is_na":true}]},{"code":"FAQ_04","no":4,"text":"参加需技巧性的游戏或活动（如打扑克、下棋、打麻将、绘画、摄影、集邮、书法、木工）","domain":null,"max_score":3.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"0","text":"没有任何困难，能独立完成，不需他人帮助","score":0.0,"is_na":false},{"code":"1","text":"有些困难，需要他人指导或监督","score":1.0,"is_na":false},{"code":"2","text":"需要帮助才能完成，部分依赖","score":2.0,"is_na":false},{"code":"3","text":"本人无法完成，或完全由他人代替完成","score":3.0,"is_na":false},{"code":"NA","text":"该项目不适合，或老人从来不做","score":0.0,"is_na":true}]},{"code":"FAQ_05","no":5,"text":"使用各种电器（如电视、空调、微波炉、电饭煲）","domain":null,"max_score":3.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"0","text":"没有任何困难，能独立完成，不需他人帮助","score":0.0,"is_na":false},{"code":"1","text":"有些困难，需要他人指导或监督","score":1.0,"is_na":false},{"code":"2","text":"需要帮助才能完成，部分依赖","score":2.0,"is_na":false},{"code":"3","text":"本人无法完成，或完全由他人代替完成","score":3.0,"is_na":false},{"code":"NA","text":"该项目不适合，或老人从来不做","score":0.0,"is_na":true}]},{"code":"FAQ_06","no":6,"text":"准备和烧一顿饭菜（包括加工蔬菜、使用炉子、调味品用量恰当）","domain":null,"max_score":3.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"0","text":"没有任何困难，能独立完成，不需他人帮助","score":0.0,"is_na":false},{"code":"1","text":"有些困难，需要他人指导或监督","score":1.0,"is_na":false},{"code":"2","text":"需要帮助才能完成，部分依赖","score":2.0,"is_na":false},{"code":"3","text":"本人无法完成，或完全由他人代替完成","score":3.0,"is_na":false},{"code":"NA","text":"该项目不适合，或老人从来不做","score":0.0,"is_na":true}]},{"code":"FAQ_07","no":7,"text":"关心和了解新鲜事物（国家大事或邻居中发生的重要事情）","domain":null,"max_score":3.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"0","text":"没有任何困难，能独立完成，不需他人帮助","score":0.0,"is_na":false},{"code":"1","text":"有些困难，需要他人指导或监督","score":1.0,"is_na":false},{"code":"2","text":"需要帮助才能完成，部分依赖","score":2.0,"is_na":false},{"code":"3","text":"本人无法完成，或完全由他人代替完成","score":3.0,"is_na":false},{"code":"NA","text":"该项目不适合，或老人从来不做","score":0.0,"is_na":true}]},{"code":"FAQ_08","no":8,"text":"持续一小时以上注意力集中地看电视或小说，或收听收音机并能理解、评论或讨论其内容","domain":null,"max_score":3.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"0","text":"没有任何困难，能独立完成，不需他人帮助","score":0.0,"is_na":false},{"code":"1","text":"有些困难，需要他人指导或监督","score":1.0,"is_na":false},{"code":"2","text":"需要帮助才能完成，部分依赖","sco