INSERT INTO scale_configs (scale_config_id, scale_code, name, version, category, source_document, instructions, items, scoring, stimulus_assets, status) VALUES ('mmse-1.0', 'MMSE', '简明精神状态检查', '1.0', 'cognitive', '1_AD临床前期SCD筛查量表-基线期-加上情景选择题.pdf', '["对患者进行定向、记忆、注意与计算、语言、视空间等 11 个认知域的检查，每题回答正确得 1 分。节点分数：17 分（文盲）、20 分（1-6 年）、24 分（>6 年）。"]'::jsonb, '[{"code":"MMSE_01","no":1,"text":"现在是哪一年？","domain":"时间定向","max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"1","text":"正确","score":1.0,"is_na":false},{"code":"0","text":"错误","score":0.0,"is_na":false}]},{"code":"MMSE_02","no":2,"text":"现在是什么季节？","domain":"时间定向","max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"1","text":"正确","score":1.0,"is_na":false},{"code":"0","text":"错误","score":0.0,"is_na":false}]},{"code":"MMSE_03","no":3,"text":"现在是几月份？","domain":"时间定向","max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"1","text":"正确","score":1.0,"is_na":false},{"code":"0","text":"错误","score":0.0,"is_na":false}]},{"code":"MMSE_04","no":4,"text":"今天是几号？","domain":"时间定向","max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"1","text":"正确","score":1.0,"is_na":false},{"code":"0","text":"错误","score":0.0,"is_na":false}]},{"code":"MMSE_05","no":5,"text":"今天是星期几？","domain":"时间定向","max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"1","text":"正确","score":1.0,"is_na":false},{"code":"0","text":"错误","score":0.0,"is_na":false}]},{"code":"MMSE_06","no":6,"text":"我们现在在什么城市？","domain":"地点定向","max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"1","text":"正确","score":1.0,"is_na":false},{"code":"0","text":"错误","score":0.0,"is_na":false}]},{"code":"MMSE_07","no":7,"text":"在什么城区（区/县）？","domain":"地点定向","max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"1","text":"正确","score":1.0,"is_na":false},{"code":"