INSERT INTO scale_configs (scale_config_id, scale_code, name, version, category, source_document, instructions, items, scoring, stimulus_assets, status) VALUES ('moca_b-1.0', 'MOCA_B', '蒙特利尔认知评估基础量表（中文版）', '1.0', 'cognitive', '4.最新量表操作说明修订版.pdf', '["涵盖执行功能、词语流畅性、定向、计算、抽象、延迟回忆、视知觉、命名、注意等认知域。节点（异常值指小于等于节点）：文盲/小学 19 分、中学 22 分、大学 24 分。"]'::jsonb, '[{"code":"MOCA_B_01","no":1,"text":"执行功能（连线）：按数字到点逐渐升高的顺序连线","domain":"执行功能","max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"1","text":"完全按顺序连线","score":1.0,"is_na":false},{"code":"0","text":"出现任何错误","score":0.0,"is_na":false}]},{"code":"MOCA_B_02","no":2,"text":"词语流畅性：1 分钟内说出水果名称","domain":"词语流畅性","max_score":2.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"2","text":"≥13 个","score":2.0,"is_na":false},{"code":"1","text":"8-12 个","score":1.0,"is_na":false},{"code":"0","text":"≤7 个","score":0.0,"is_na":false}]},{"code":"MOCA_B_03","no":3,"text":"现在是几点钟？","domain":"定向","max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"1","text":"正确","score":1.0,"is_na":false},{"code":"0","text":"错误","score":0.0,"is_na":false}]},{"code":"MOCA_B_04","no":4,"text":"现在是哪一年？","domain":"定向","max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"1","text":"正确","score":1.0,"is_na":false},{"code":"0","text":"错误","score":0.0,"is_na":false}]},{"code":"MOCA_B_05","no":5,"text":"现在是几月份？","domain":"定向","max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"1","text":"正确","score":1.0,"is_na":false},{"code":"0","text":"错误","score":0.0,"is_na":false}]},{"code":"MOCA_B_06","no":6,"text":"今天是星期几？","domain":"定向","max_score":1.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"1","text":"正确","score":1.0,"is_na":false},{"code":"0","text":"错误","score":0.0,"is_na":false}]},{"code":"MOCA_B_07","no":7,"text":"这是什么地方（医院/诊所/办公室名称）？","domain":"定向","max_score":1.0,"score_method":"DIRE