INSERT INTO scale_configs (scale_config_id, scale_code, name, version, category, source_document, instructions, items, scoring, stimulus_assets, status) VALUES ('cdr-1.0', 'CDR', '临床痴呆评定量表', '1.0', 'cognitive', '5.CDR.pdf', '["分别对知情者和受试者本人进行访谈。只有当能力的减退是由认知障碍引起时才计分。6 个功能域各记 0 / 0.5 / 1 / 2 / 3 分；以记忆力为主要项目、其余 5 项为次要项目，按 Morris 规则综合出整体 CDR；CDR-SB = 6 域得分之和。"]'::jsonb, '[{"code":"CDR_MEMORY","no":1,"text":"记忆力（主要项目）","domain":"记忆力","max_score":3.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"0","text":"无记忆缺损或只有轻微的、偶尔的健忘","score":0.0,"is_na":false},{"code":"0.5","text":"经常性的轻微健忘；对事情能部分回忆；「良性健忘」","score":0.5,"is_na":false},{"code":"1","text":"中度记忆缺损，对近事遗忘突出，记忆缺损妨碍日常活动","score":1.0,"is_na":false},{"code":"2","text":"严重记忆缺损；能记住过去非常熟悉的事情，新发生的事件很快遗忘","score":2.0,"is_na":false},{"code":"3","text":"严重记忆丧失；仅存片段的记忆","score":3.0,"is_na":false}]},{"code":"CDR_ORIENTATION","no":2,"text":"定向力","domain":"定向力","max_score":3.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"0","text":"能完全正确定向","score":0.0,"is_na":false},{"code":"0.5","text":"对时间关联性有轻微的困难，其余能完全正确定向","score":0.5,"is_na":false},{"code":"1","text":"对时间关联性有中度困难；检查时对地点仍有定向能力；但在某些场合可能有地理定向能力障碍","score":1.0,"is_na":false},{"code":"2","text":"对时间关联性有严重困难；通常对时间不能定向，常有地点失定向","score":2.0,"is_na":false},{"code":"3","text":"仅对病人自己有定向力","score":3.0,"is_na":false}]},{"code":"CDR_JUDGMENT","no":3,"text":"判断与解决问题的能力","domain":"判断与解决问题","max_score":3.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"0","text":"能很好地解决日常问题，处理事务和财务，判断力良好","score":0.0,"is_na":false},{"code":"0.5","text":"在解决问题、辨别事物间的异同点方面有轻微缺损","score":0.5,"is_na":false},{"code":"1","text":"在解决问题、辨别事物间的异同点方面有中度困难；通常还能维持社交事务判断力","score":1.0,"is_na":false},{"code":"2","text":"在解决问题、辨别事物间的异同点方面有严重损害；社会判断力通常受损","score":2.0,"is_na":false},{"code":"3","text":"不能做判断，或不能解决问题","score":3.0,"is_na":false}]},{"code":"CDR_COMMUNITY","no":4,"text":"社会事务","domain":"社会事务","max_score":3.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"0","text":"和平常一样能独立处理工作、购物、义务劳动及社会群体活动","score":0.0,"is_na":false},{"code":"0.5","text":"在这些活动方面仅有轻微损害","score":0.5,"is_na":false},{"code":"1","text":"已不能独立进行这些活动；可以从事其中部分活动，不经意的观察似乎正常","score":1.0,"is_na":false},{"code":"2","text":"不能独立进行室外活动；但可被带到家庭以外的场所参加活动","score":2.0,"is_na":false},{"code":"3","text":"不能独立进行室外活动；病重得不能被带到家庭以外的场所参加活动","score":3.0,"is_na":false}]},{"code":"CDR_HOME","no":5,"text":"家务与业余爱好","domain":"家务与业余爱好","max_score":3.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"0","text":"家庭生活、业余爱好和需用智力的兴趣均很好保持","score":0.0,"is_na":false},{"code":"0.5","text":"家庭生活、业余爱好和需用智力的兴趣有轻微损害","score":0.5,"is_na":false},{"code":"1","text":"家庭活动有肯定的轻度障碍，放弃难度大的家务，放弃复杂的爱好和兴趣","score":1.0,"is_na":false},{"code":"2","text":"仅能做简单的家务，兴趣明显受限，而且维持的差","score":2.0,"is_na":false},{"code":"3","text":"丧失有意义的家庭活动","score":3.0,"is_na":false}]},{"code":"CDR_PERSONAL_CARE","no":6,"text":"个人自理能力","domain":"个人自理","max_score":3.0,"score_method":"DIRECT","required":true,"remark":"","options":[{"code":"0","text":"完全自理","score":0.0,"is_na":false},{"code":"0.5","text":"完全自理","score":0.5,"is_na":false},{"code":"1","text":"须旁人督促或提醒","score":1.0,"is_na":false},{"code":"2","text":"穿衣、个人卫生及个人事务料理都需要帮助","score":2.0,"is_na":false},{"code":"3","text":"个人自理方面依赖别人给予很大帮助；经常大小便失禁","score":3.0,"is_na":false}]}]'::jsonb, '{"scoringType":"CDR","scoreMin":0.0,"scoreMax":3.0,"cutoffs":[],"remark":"CDR 整体评分与 CDR-SB 由算法计算，详见 scoring/scales/cdr.py。","algorithmSource":"scoring/scales/cdr.py"}'::jsonb, '[]'::jsonb, 'draft');
